"""Complete 24 original snakebite and other envenomation questions."""
from create_critical_snakebite import rows,q,WH,IN,ref
from qbank_authoring import finalize
SC=ref('Randomized trial of antivenom plus prazosin for Indian red scorpion envenoming','https://doi.org/10.1136/bmj.c7136')
AN=ref('Resuscitation Council UK special circumstances: 2025','https://www.resus.org.uk/professional-library/2025-resuscitation-guidelines/special-circumstances-guidelines')

q('After a viper bite, a patient has oliguria, rising creatinine and hyperkalemia. Which statement about treatment is correct?', 'Antivenom and cause-directed care do not remove the need for dialysis when urgent AKI complications develop',[
 ('Antivenom immediately reverses all established kidney injury','Kidney damage may persist despite venom neutralization.'),('A loop diuretic response proves that dialysis can never be required','Urine volume does not establish adequate solute clearance.'),('Dialysis must wait for the bite wound to heal','Life-threatening electrolyte, acid-base or fluid complications require prompt support.')],
 'Venom neutralization and kidney support address different problems','**Snakebite AKI can involve shock, pigment injury, direct toxicity and microvascular injury.**',['Treat volume/perfusion problems without causing overload.','Avoid nephrotoxins and monitor potassium and acid-base status.'],'**Use standard urgent RRT indications and an appropriate modality.**',['Follow urine output and renal recovery after the acute phase.','Antivenom selection and timing remain important when ongoing envenoming is present.'],[['Specific treatment','Neutralize accessible venom'],['Kidney support','Treat organ failure complications'],['Follow-up','Renal recovery/CKD assessment']],[WH,IN],style='clinical_scenario')

q('Following snakebite, anemia with schistocytes, thrombocytopenia and severe AKI persist after the major clotting abnormality improves. Which complication should be considered?', 'Snakebite-associated thrombotic microangiopathy',[
 ('Isolated iron deficiency','This does not explain acute fragmentation and thrombocytopenia.'),('Simple dilutional anemia as a complete explanation','Dilution does not explain the microangiopathic pattern and kidney injury.'),('ITP as established solely by the platelet count','The hemolysis and organ injury indicate a broader process.')],
 'Reassess when the syndrome outlasts coagulopathy','**A microangiopathic process can complicate selected envenomations.**',['Hemolysis, platelets, kidney function and coagulation trends help separate overlapping mechanisms.','Do not automatically equate this with immune TTP.'],'**Provide organ support and specialist evaluation.**',['The role of plasma exchange is not established as universal treatment for snakebite-associated TMA.','Investigate alternative TMA causes when appropriate.'],[['Hemolysis','Schistocytes/biochemical evidence'],['Platelets','Reduced'],['Kidney','Often prominently affected']],[WH],style='clinical_scenario')

q('A snakebite patient has a markedly swollen limb but preserved distal perfusion. What is the appropriate approach to suspected compartment syndrome?', 'Assess objectively and correct envenoming/coagulopathy before considering fasciotomy for confirmed compartment syndrome',[
 ('Perform fasciotomy for swelling alone','Venom edema can mimic compartment syndrome and surgery can cause severe bleeding.'),('Exclude compartment syndrome solely because pulses are present','Pulses may persist despite dangerous compartment pressure.'),('Apply a tighter tourniquet to reduce swelling','This worsens ischemic risk.')],
 'Swelling is not sufficient evidence for surgery','**Unnecessary fasciotomy can add hemorrhage, infection and tissue damage.**',['Assess pain, neurological findings, perfusion and pressure when indicated.','Antivenom and hemostatic management may reduce the underlying process.'],'**Obtain experienced surgical/toxicology input for a confirmed pressure syndrome.**',['Do not delay necessary decompression once the diagnosis is established.','Avoid casual invasive procedures while blood is incoagulable.'],[['Swelling','Common venom effect'],['Pulses','Do not exclude syndrome'],['Fasciotomy','Confirmed indication and hemostatic planning']],[WH,IN],style='clinical_scenario')

q('Which laboratory pattern after sea-snake envenoming most strongly supports venom-related rhabdomyolysis?', 'Marked CK elevation with myoglobinuria and hyperkalemia',[
 ('Isolated raised alkaline phosphatase','This is not the characteristic muscle-injury marker.'),('Low CK with isolated unconjugated bilirubin elevation','This favors a different process such as hemolysis.'),('A positive urine protein dipstick alone','This does not establish muscle pigment release.')],
 'Myotoxic venom can create both respiratory and renal danger','**Muscle injury releases potassium and myoglobin.**',['Generalized myalgia and weakness may accompany the biochemical changes.','A heme-positive urine dipstick with few red cells can suggest pigment.'],'**Monitor ECG, renal function, electrolytes and respiratory strength.**',['Use an effective antivenom where indicated and available.','Tailor fluids to perfusion and renal/cardiac tolerance.'],[['Muscle marker','CK'],['Pigment','Myoglobin'],['Immediate hazard','Hyperkalemia/respiratory weakness']],[WH])

q('After a suspected snakebite, examination and first laboratory tests are normal. Which conclusion is appropriate?', 'Dry bite is possible, but serial observation is needed before excluding evolving envenoming',[
 ('A normal first examination permanently excludes venom injection','Neurotoxicity and coagulopathy can be delayed.'),('All patients should receive prophylactic antivenom regardless of findings','Unnecessary treatment exposes patients to reactions without demonstrated benefit.'),('Fang marks prove systemic poisoning even if repeated assessment remains normal','Marks establish possible exposure rather than systemic effect.')],
 'Absence of early signs is a time-dependent finding','**Venom effects may evolve after presentation.**',['Observation duration follows the regional syndrome/species protocol.','Repeat neurological, local and coagulation assessment as indicated.'],'**Provide explicit escalation and return instructions.**',['Watch for ptosis, swallowing/breathing difficulty, bleeding and spreading swelling.','Document the bite and assessment times.'],[['Initial normal findings','Not final exclusion'],['Monitoring','Serial clinical/laboratory review'],['Antivenom','Only when indicated']],[WH,IN],style='clinical_scenario')

q('Should antivenom be injected directly into a snakebite wound to neutralize local venom?', 'No; indicated antivenom is administered by the recommended systemic route',[
 ('Yes; local injection is more effective than IV treatment for systemic toxicity','It does not adequately treat systemic envenoming and can injure tissue.'),('Yes; it removes the need for respiratory support','No injection route substitutes for ventilation.'),('Yes; it prevents all necrosis already established','Antivenom cannot restore dead tissue.')],
 'Use the validated administration route','**Local wound infiltration is not the standard antivenom treatment.**',['Product-specific IV preparation and monitoring are required.','Systemic neutralization should occur before additional venom injury when possible.'],'**Provide appropriate wound care and tetanus assessment separately.**',['Avoid routine traumatic procedures and unnecessary injections in coagulopathy.','Assess infection on clinical evidence rather than assuming all swelling is bacterial.'],[['Antivenom','Recommended systemic route'],['Wound','Separate local care'],['Established necrosis','Not instantly reversible']],[WH,IN])

q('A child with an Indian red scorpion sting develops sweating, cold extremities, tachycardia and hypertension. Which physiological process is central?', 'An autonomic storm with major catecholamine-mediated cardiovascular effects',[
 ('A purely local histamine reaction with no cardiac risk','Systemic autonomic findings can precede myocardial dysfunction and pulmonary edema.'),('Primary acetylcholinesterase inhibition identical to organophosphate poisoning','Scorpion venom acts through different neurotoxic mechanisms.'),('An isolated hypovolemic process from blood loss at the sting','The puncture does not explain the systemic cardiovascular syndrome.')],
 'Local pain can precede dangerous systemic toxicity','**Scorpion venom can disrupt ion-channel function and trigger autonomic discharge.**',['Cardiovascular dysfunction is particularly dangerous in children.','The pattern varies across species and geography.'],'**Assess perfusion, respiratory state and cardiac function.**',['Use regional species-specific treatment guidance.','Treat pulmonary edema and shock according to the hemodynamic phenotype.'],[['Early systemic clues','Sweating/cold limbs'],['Mechanism','Autonomic discharge'],['Severe risk','Cardiac dysfunction/pulmonary edema']],[SC],style='clinical_scenario')

q('What is the principal rationale for prazosin in appropriate Indian red scorpion envenoming?', 'Alpha-1 blockade reduces catecholamine-mediated vasoconstriction and cardiac loading',[
 ('Direct antibody neutralization of venom','That is the role of a species-effective antivenom.'),('Acetylcholinesterase reactivation','That is the intended oxime mechanism in selected organophosphate poisoning.'),('Direct removal of circulating venom by renal chelation','Prazosin is not a chelator.')],
 'Physiological treatment complements venom neutralization','**Prazosin targets the adrenergic consequences of the autonomic storm.**',['Benefit depends on the clinical setting and regional protocol.','Hypotension and shock require careful individualized administration and support.'],'**Use alongside indicated antivenom and cardiopulmonary care.**',['Do not assume oral medication replaces ICU support in severe shock.','Monitor blood pressure, perfusion and pulmonary edema closely.'],[['Prazosin','Alpha-1 blockade'],['Antivenom','Venom neutralization'],['Organ support','Treat failure already present']],[SC])

q('In a randomized Indian red scorpion study, what did adding effective antivenom to prazosin support?', 'Faster clinical recovery than prazosin alone in the studied envenoming population',[
 ('Proof that prazosin is unnecessary in every patient','The comparison evaluated addition to prazosin, not universal replacement.'),('Proof that all scorpion antivenoms work against all species','Antivenom specificity and geography remain important.'),('Elimination of the need for ventilation in every severe case','Severe cardiopulmonary failure can still require support.')],
 'Do not extend a species-specific trial beyond its setting','**Antivenom and prazosin act at different points in the causal pathway.**',['The trial supports a combined approach in the studied setting.','Severity, timing and product efficacy affect the likely benefit.'],'**Apply local evidence and monitor the actual clinical response.**',['Provide escalation for myocardial dysfunction or pulmonary edema.','Check that the product covers the relevant species.'],[['Antivenom','Upstream toxin neutralization'],['Prazosin','Downstream adrenergic effects'],['Evidence','Population/product specific']],[SC])

q('Following a bee sting, an adult has wheeze and hypotension with a pulse. What is the immediate first-line drug?', 'Intramuscular epinephrine',[
 ('An oral antihistamine as the sole urgent treatment','It does not reverse shock or airway compromise.'),('Hydrocortisone before epinephrine','Steroids do not provide immediate life-saving reversal.'),('A beta blocker for tachycardia','This can worsen anaphylaxis and hinder treatment.')],
 'Anaphylaxis treatment is based on the systemic syndrome','**Epinephrine treats airway, respiratory and circulatory features.**',['Remove the exposure/stinger when feasible without delaying treatment.','Position, oxygen, fluids and airway support are important adjuncts.'],'**Repeat treatment and escalate according to response.**',['Persistent shock may need a monitored infusion under expert care.','Observe according to severity and recurrence risk.'],[['First-line','IM epinephrine'],['Adjuncts','Airway/oxygen/fluids'],['Antihistamines','Skin symptoms; not shock rescue']],[AN],style='clinical_scenario')

q('After hundreds of bee stings, a patient develops AKI, high CK and dark urine without initial urticaria or bronchospasm. Which interpretation is most appropriate?', 'Massive venom exposure can cause direct systemic toxicity including rhabdomyolysis and hemolysis independently of anaphylaxis',[
 ('No anaphylaxis means there is no systemic danger','Toxic venom burden and allergy are distinct mechanisms.'),('All organ injury must be explained by IgE-mediated allergy','Direct toxicity can occur without the classic allergic syndrome.'),('A normal initial ECG excludes delayed kidney injury','Biochemical and renal complications can evolve later.')],
 'Dose-related envenoming differs from allergic sensitivity','**Multiple stings can deliver a large systemic toxin load.**',['Monitor muscle injury, hemolysis, potassium and kidney function.','Anaphylaxis may coexist but is not required.'],'**Provide monitored organ support and serial assessment.**',['Treat hyperkalemia and other urgent complications promptly.','Tailor fluids and dialysis decisions to physiology.'],[['Allergy','Can follow a single sting'],['Toxic burden','Increases with numerous stings'],['Delayed risk','Muscle/renal and other organ injury']],[ref('ISCCM approach to poisoning position statement','https://pmc.ncbi.nlm.nih.gov/articles/PMC11369925/')],style='clinical_scenario')

q('A snakebite survivor has persistent disability, weakness and fear of returning to work. Which follow-up plan is appropriate?', 'Assess physical function, renal recovery, wound sequelae and psychological needs with rehabilitation',[
 ('End follow-up once antivenom infusion is complete','Neutralization does not ensure complete functional recovery.'),('Assume all symptoms represent ongoing free venom requiring repeated antivenom','Established injury and recovery needs are distinct from ongoing envenoming.'),('Restrict evaluation to the appearance of the bite scar','Important systemic and psychological sequelae can remain.')],
 'Survival is not the only meaningful outcome','**Snakebite can leave renal, neurological, tissue and psychological consequences.**',['The required follow-up depends on the original syndrome.','Work participation and family burden are relevant outcomes.'],'**Create a cause- and function-based recovery plan.**',['Refer for rehabilitation and wound care as indicated.','Provide prevention education without blaming the patient.'],[['Physical','Strength, wound and mobility'],['Systemic','Kidney and other organ recovery'],['Psychological','Anxiety and participation']],[WH],style='clinical_scenario')

if __name__=='__main__':finalize('Critical Care and Toxicology',6,'Snakebite and Envenomation','critical-envenomation',rows,24)
